\label{classical-carleson}



Let $f$ be a $2\pi$-periodic complex-valued continuous function on $\mathbb{R}$.
Then for almost all $x \in \mathbb{R}$ we have
\begin{equation}\label{eq:fourier-limit}
  \lim_{N\to\infty}S_N f(x) = f(x),
\end{equation}
where $S_N f$ is the $N$-th partial Fourier sum of $f$ defined in \eqref{eq:trig-series}
with coefficients \eqref{eq:fourier-coefficients}.

Let
\begin{equation}
    a\ge 4
\end{equation}
be a natural number that as it gets larger will allow for more general applications of Theorem \ref{metric-space-Carleson}
but will worsen the constants in the estimates.

Further, a compatible collection ${\Theta}$ is called cancellative, if
for any ball $B$ in $X$ of radius $R$, any Lipschitz function $\varphi: X\to \C$
supported on $B$, and any ${\vartheta},{\theta}\in {\Theta}$ we have
\begin{equation}
    \label{eq-vdc-cond}
    |\int_B e({\vartheta}(x)-{{\theta}(x)}) \varphi(x) d\mu(x)|\le 2^a \mu(B)\|\varphi\|_{\operatorname{Lip}(B)}
(1+d_B({\vartheta},{\theta}))^{-\frac{1}{a}},
\end{equation}
where $\|\cdot\|_{\operatorname{Lip}(B)}$ denotes the inhomogeneous Lipschitz norm on $B$:
$$
    \|\varphi\|_{\operatorname{Lip}(B)} = \sup_{x \in B} |\varphi(x)| + R \sup_{x,y \in B, x \neq y} \frac{|\varphi(x) - \varphi(y)|}{\rho(x,y)}\,.
$$

\begin{equation}
    \label{def-main-op}
    Tf(x):=\sup_{{\vartheta}\in{\Theta}} \sup_{0 < R_1 < R_2}\left| \int_{R_1 < \rho(x,y) < R_2} K(x,y) f(y) e({\vartheta}(y)) \, \mathrm{d}\mu(y) \right|\, ,
\end{equation}

\label{metric-space-Carleson}



    For all integers $a \ge 4$ and real numbers $1<q\le 2$ the following holds.
    Let $(X,\rho,\mu,a)$ be a doubling metric measure space.
    Let ${\Theta}$ be a cancellative compatible collection of functions and let $K$ be a one-sided Calder\'on--Zygmund kernel on $(X,\rho,\mu,a)$.
    Assume that for every bounded measurable function $g$ on $X$ supported on a set of finite measure we have
    \begin{equation}\label{nontanbound}
        \|T_{*}g\|_{2} \leq 2^{a^3} \|g\|_2\,,
    \end{equation}
    where $T_{*}$ is defined in \eqref{def-tang-unm-op}.
    Then for all Borel sets $F$ and $G$ in $X$ and all Borel functions $f:X\to \C$ with
    $|f|\le \mathbf{1}_F$, we have, with $T$ defined in \eqref{def-main-op},
    \begin{equation}
        \label{resweak}
        \left|\int_{G} T f \, \mathrm{d}\mu\right| \leq \frac{2^{443a^3}}{(q-1)^6} \mu(G)^{1-\frac{1}{q}} \mu(F)^{\frac{1}{q}}\, .
    \end{equation}

\begin{equation}
    \label{def-lin-main-op}
    T_{Q} f(x):= \sup_{0 < R_1 < R_2}\left| \int_{R_1 < \rho(x,y) < R_2} K(x,y) f(y) e({Q}(x)(y)) \, \mathrm{d}\mu(y) \right|\, ,
\end{equation}

\label{linearised-metric-Carleson}



    For all integers $a \ge 4$ and real numbers $1<q\le 2$ the following holds.
    Let $(X,\rho,\mu,a)$ be a doubling metric measure space. Let ${\Theta}$ be a
    cancellative compatible collection of functions.
    Let ${Q}:X\to {\Theta}$ be a Borel function with finite range.
    Let $K$ be a one-sided Calder\'on--Zygmund kernel on $(X,\rho,\mu,a)$. Assume that for every ${\vartheta}\in {\Theta}$ and every bounded measurable function $g$ on $X$ supported on a set of finite measure we have
    \begin{equation}\label{linnontanbound}
        \|T_{{Q}}^{\vartheta} g\|_{2} \leq 2^{a^3} \|g\|_2\,,
    \end{equation}
    where $T_{{Q}}^{\vartheta}$ is defined in \eqref{def-lin-star-op}.
    Then for all Borel sets $F$ and $G$ in $X$ and all Borel functions $f:X\to \C$ with
    $|f|\le \mathbf{1}_F$, we have, with $T_{Q}$ defined in \eqref{def-lin-main-op},
    \begin{equation}
        \label{linresweak}
        \left|\int_{G} T_{Q} f \, \mathrm{d}\mu\right| \le \frac{2^{443a^3}}{(q-1)^6} \mu(G)^{1-\frac{1}{q}} \mu(F)^{\frac{1}{q}}\, .
    \end{equation}

Let
 $\psi:{\mathbb{R}} \to {\mathbb{R}}$ be the unique compactly supported, piece-wise linear, continuous function with corners precisely at $\frac 1{4D}$, $\frac 1{2D}$, $\frac 14$ and $\frac 12$ which satisfies
 \begin{equation}
    \label{eq-psisum}
    \sum_{s\in \mathbb{Z}} \psi(D^{-s}x)=1
\end{equation}
for all $x>0$.

For $s\in\mathbb{Z}$, we define
\begin{equation}\label{defks}
    K_s(x,y):=K(x,y)\psi(D^{-s}\rho(x,y))\,,
\end{equation}
so that for each $x, y \in X$ with $x\neq y$ we have
$$K(x,y)=\sum_{s\in\mathbb{Z}}K_s(x,y).$$

