    \sum_{{\mathfrak p}\in {\mathfrak P}}T_{{\mathfrak p}} f(x)= \sum_{s=\sigma_1(x)}^{\sigma_2(x)}
    \int K_{s}(x,y) f(y) e({Q}(x)(y)-{Q}(x)(x))\, d\mu(y).
\end{equation}

\begin{equation}\label{eq-sump}
        \sum_{{\mathfrak p}\in {\mathfrak P}}T_{{\mathfrak p}} f(x)= \sum_{s=\sigma_1(x)}^{\sigma_2(x)}
        \int K_{s}(x,y) f(y) e({Q}(x)(y)-{Q}(x)(x))\, d\mu(y).
    \end{equation}

\begin{equation}\label{insump}
        \sum_{{\mathfrak p}\in {\mathfrak P}: {\mathrm{s}}({\mathfrak p})=s}T_{{\mathfrak p}} f(x)=
        \int K_{s}(x,y) f(y) e({Q}(x)(y) - {Q}(x)(x))\, d\mu(y).
    \end{equation}

We now estimate with \Cref{tile-sum-operator} and \Cref{discrete-Carleson}
\begin{equation}
 \int_{G \setminus G'} \left|\sum_{s={\sigma_1}(x)}^{{\sigma_2}(x)} \int K_s(x,y) f(y) e({Q}(x)(y)) \, \mathrm{d}\mu(y)\right| \mathrm{d}\mu(x)
\end{equation}
\begin{equation}
 =\int_{G \setminus G'} \left|\sum_{s={\sigma_1}(x)}^{{\sigma_2}(x)} \int K_s(x,y) f(y) e({Q}(x)(y) - {Q}(x)(x))\mathrm{d}\mu(y)\right| \mathrm{d}\mu(x)
\end{equation}
\begin{equation}
 =\int_{G \setminus G'} \left|\sum_{{\mathfrak p}\in {\mathfrak P}}T_{{\mathfrak p}} f(x)\right| \mathrm{d}\mu(x)
 \le \frac{2^{442a^3}}{(q-1)^5} \mu(G)^{1 - \frac{1}{q}} \mu(F)^{\frac{1}{q}} \,.
\end{equation}
This proves \eqref{eq-linearized} for the chosen set $G'$ and arbitrary $f$ and thus completes the proof of Proposition
\ref{finitary-Carleson}.

