\label{frequency-ball-doubling}



  For any $x,x'\in {\mathbb{R}}$ and $R>0$ with
   $x\in B(x',2R)$ and any $n,m\in \mathbb{Z}$, we have
\begin{equation}\label{firstdb1}
    d_{B(x',2R)}({\vartheta}_n,{\vartheta}_m)\le 2 d_{B(x,R)}({\vartheta}_n,{\vartheta}_m) \, .
\end{equation}

\label{frequency-ball-growth}


    For any $x,x'\in {\mathbb{R}}$ and $R>0$ with
   $B(x,R)\subset B(x',2R)$ and any $n,m\in \mathbb{Z}$, we have
\begin{equation}\label{seconddb1}
    2d_{B(x,R)}({\vartheta}_n,{\vartheta}_m)\le d_{B(x',2R)}({\vartheta}_n,{\vartheta}_m) \, .
\end{equation}

    \label{integer-ball-cover}


    For every $x\in {\mathbb{R}}$ and $R>0$ and every
    $n\in \mathbb{Z}$ and $R'>0$,
    there exist $m_1, m_2, m_3\in \mathbb{Z}$
    such that
    \begin{equation}\label{eqcarl5}
        B'\subset B_1\cup B_2\cup B_3\, ,
    \end{equation}
where
\begin{equation}
B'= \{ {\vartheta} \in {\Theta}: d_{B(x,R)}({\vartheta}, {\vartheta}_n)<2R'\}
\end{equation}
and for $j=1,2,3$
\begin{equation}
  B_j=
     \{ {\vartheta} \in {\Theta}: d_{B(x,R)}({\vartheta}, {\vartheta}_{m_j})<R'\}
     \, .
\end{equation}

Let $m_1$ be the largest integer smaller than
or equal to
$n- \frac {R'} {2R}$.
Let $m_2=n$.
Let $m_3$ be the smallest integer larger than
or equal to $n+ \frac {R'} {2R}$.

Let ${\vartheta}_{n'}\in B'$, then with \eqref{eqcarl4},
we have
\begin{equation}\label{eqcarl6}
    2R|n-n'|< 2R'\, .
\end{equation}

Assume first $n'\le m_1$. With \eqref{eqcarl6}
we have
\begin{equation*}
    R|m_1-n'|=R(m_1-n')=R(m_1-n)+R(n-n')
\end{equation*}
\begin{equation}
    < -\frac{R'}2+R'=-\frac{R'}2\, .
\end{equation}
We conclude ${\vartheta}_{n'}\in B_1$.

Assume next $m_1<n'<m_3$. Then
${\vartheta}_{n'}\in B_2$.

Assume finally that $m_3\le n'$. With \eqref{eqcarl6}
we have
\begin{equation*}
    R|m_3-n'|=R(n'-m_3)=R(n'-n)+R(n-m_3)
\end{equation*}
\begin{equation}
    < R' -\frac{R'}2=-\frac{R'}2\, .
\end{equation}
We conclude ${\vartheta}_{n'}\in B_1$.
This completes the proof of the lemma.

